1	<class 'list'> [('getting-started', 'Getting started', 52), ('projects', 'Projects and media', 125), ('timeline', 'Timeline and playback', 95), ('editing', 'Editing', 92), ('canvas', 'Canvas and layers', 82), ('text-and-shapes', 'Text, shapes and pictures', 71), ('effects', 'Effects and keying', 76), ('motion', 'Motion and transitions', 173), ('speed', 'Speed', 107), ('audio', 'Audio', 194), ('cleanup', 'Clean-up tools', 64), ('captions', 'Captions and transcript', 143), ('color', 'Colour', 191), ('hdr', 'HDR and colour management', 83), ('graphics', 'Motion graphics', 187), ('framing', 'Vertical and framing', 92), ('multicam', 'Multicam', 52), ('recording', 'Recording', 172), ('export', 'Export', 103), ('assistant', 'The Assistant', 94), ('mcp', 'Agents and MCP', 219), ('reference', 'Reference', 140)]
2	{'id': 'assistant', 'title': 'The Assistant'}
3	94
4	{"id": "assistant-your-own-key", "name": "Your own Anthropic key", "summary": "The Assistant runs on your own Anthropic API key, so Anthropic bills its usage to your account and there is no Frame Job account or relay.", "page": "assistant/set-up", "anchor": "your-own-anthropic-key", "where": "Frame Job ▸ Settings… (⌘,) ▸ Assistant", "needs": "your Anthropic key"}
5	{"id": "assistant-settings-section", "name": "The Assistant section of Settings", "summary": "Settings has an Assistant section holding the key, the model and the chat settings.", "page": "assistant/set-up", "anchor": "open-settings", "where": "Frame Job ▸ Settings… (⌘,) ▸ Assistant", "keys": "⌘,"}
6	{"id": "assistant-save-key", "name": "Save your Anthropic API key", "summary": "Paste your key into the secure Anthropic API key field and click Save or press Return; it is never shown again.", "page": "assistant/set-up", "anchor": "save-your-key", "where": "Frame Job ▸ Settings… (⌘,) ▸ Assistant ▸ Anthropic API key:"}
7	{"id": "assistant-remove-key", "name": "Remove the saved key", "summary": "Remove deletes the saved key.", "page": "assistant/set-up", "anchor": "remove-your-key", "where": "Frame Job ▸ Settings… (⌘,) ▸ Assistant ▸ Remove"}
8	{"id": "assistant-key-status", "name": "The key's status line", "summary": "A line under the controls reports the key's state and what a Save or Remove did.", "page": "assistant/set-up", "anchor": "the-status-line", "where": "Frame Job ▸ Settings… (⌘,) ▸ Assistant, status line above Save and Remove"}
9	{"id": "assistant-no-verify", "name": "No Verify for this key", "summary": "The Anthropic key has no Verify button; it is first used when you send a message from the Assistant tab.", "page": "assistant/set-up", "anchor": "no-verify", "where": "Frame Job ▸ Settings… (⌘,) ▸ Assistant", "needs": "your Anthropic key"}
10	{"id": "assistant-model", "name": "Assistant model", "summary": "Type which Claude model the Assistant uses, or leave the field blank for the default.", "page": "assistant/set-up", "anchor": "choose-a-model", "where": "Frame Job ▸ Settings… (⌘,) ▸ Assistant ▸ Model:", "needs": "your Anthropic key"}
11	{"id": "assistant-compact-setting", "name": "Compact when context reaches", "summary": "A checkbox and token field that set when a long conversation is replaced by a summary.", "page": "assistant/set-up", "anchor": "compact-when-context-reaches", "where": "Frame Job ▸ Settings… (⌘,) ▸ Assistant ▸ Compact when context reaches … tokens", "needs": "your Anthropic key"}
12	{"id": "assistant-clear-results-setting", "name": "Clear old tool results", "summary": "A checkbox that lets Anthropic drop old tool results from what the model sees past 150,000 tokens.", "page": "assistant/set-up", "anchor": "clear-old-tool-results", "where": "Frame Job ▸ Settings… (⌘,) ▸ Assistant ▸ Clear old tool results past 150,000 tokens", "needs": "your Anthropic key"}
13	{"id": "assistant-key-model-change", "name": "A key or model change ends the conversation", "summary": "Saving or removing the key, or changing to a different model, ends the conversation in every open window, because a conversation keeps the key and model it started with.", "page": "assistant/set-up", "anchor": "what-a-change-does", "where": "Frame Job ▸ Settings… (⌘,) ▸ Assistant", "needs": "your Anthropic key"}
14	{"id": "assistant-chat-settings-live", "name": "Chat settings apply at once", "summary": "Changing the compaction or clearing settings applies to every open conversation and keeps each one going.", "page": "assistant/set-up", "anchor": "chat-settings-apply-at-once", "where": "Frame Job ▸ Settings… (⌘,) ▸ Assistant", "needs": "your Anthropic key"}
15	{"id": "assistant-settings-info", "name": "The Assistant ⓘ", "summary": "The ⓘ beside the Assistant heading sums up what is sent and to whom, what it costs, where the key is kept, and what the chat settings do.", "page": "assistant/set-up", "anchor": "what-the-info-button-says", "where": "Frame Job ▸ Settings… (⌘,) ▸ Assistant ▸ ⓘ beside the heading"}
16	{"id": "assistant-key-file", "name": "Where the key is kept", "summary": "A saved key lives in a file named anthropic-key that only your user account can read.", "page": "assistant/set-up", "anchor": "where-the-key-is-kept", "where": "~/Library/Application Support/Frame Job/anthropic-key"}
17	{"id": "assistant-settings-out-of-reach", "name": "Assistant settings are out of reach of tools", "summary": "No tool reads or writes the key, the model or the chat settings, so an agent over MCP cannot see or change them.", "page": "assistant/set-up", "anchor": "out-of-reach-of-tools", "where": "Frame Job ▸ Settings… (⌘,) ▸ Assistant"}
18	{"id": "assistant-env-key", "name": "A key from the environment", "summary": "With no saved key, Frame Job uses the ANTHROPIC_API_KEY environment variable.", "page": "assistant/set-up", "anchor": "a-key-from-the-environment", "where": "Launch Frame Job from a shell that sets ANTHROPIC_API_KEY"}
19	{"id": "assistant-no-key-prompt", "name": "The no-key prompt", "summary": "Without a key, the Assistant tab replaces the message field with a prompt and an Open Settings… button.", "page": "assistant/set-up", "anchor": "the-no-key-prompt", "where": "Inspector ▸ Assistant tab ▸ Open Settings…"}
20	{"id": "assistant-missing-helper", "name": "If the helper is missing", "summary": "The Assistant runs in a helper inside the app, and a copy of Frame Job without it says so in the transcript when you send a message.", "page": "assistant/set-up", "anchor": "if-the-helper-is-missing", "where": "Inspector ▸ Assistant tab ▸ transcript"}
21	{"id": "assistant-tab", "name": "The Assistant tab", "summary": "A conversation with Claude built into the inspector of every editor window, which reads and edits that window's project from plain-language requests.", "page": "assistant/chat", "anchor": "the-assistant-tab", "where": "Inspector ▸ Assistant tab", "keys": "⌃⌘A", "needs": "your Anthropic key"}
22	{"id": "assistant-view-menu", "name": "View ▸ Assistant", "summary": "Shows the inspector if it was hidden, switches to the Assistant tab and puts the cursor in the message field.", "page": "assistant/chat", "anchor": "open-the-assistant", "where": "View ▸ Assistant (⌃⌘A)", "keys": "⌃⌘A"}
23	{"id": "assistant-tab-layout", "name": "The tab's layout", "summary": "From top to bottom the tab has Context with Clear at its right end, Spend, the transcript, the ask-first row, and the message field with Send.", "page": "assistant/chat", "anchor": "the-tabs-layout", "where": "Inspector ▸ Assistant tab"}
24	{"id": "assistant-tab-stays", "name": "The tab stays put", "summary": "The assistant's own edits change the selection without moving you off the Assistant tab.", "page": "assistant/chat", "anchor": "the-tab-stays-put", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
25	{"id": "assistant-message-field", "name": "The message field", "summary": "Type a request in the field and press Return or click Send; the field empties once the message is taken.", "page": "assistant/chat", "anchor": "send-a-message", "where": "Inspector ▸ Assistant tab ▸ message field (\"Ask about or edit this project…\")", "needs": "your Anthropic key"}
26	{"id": "assistant-return-sends", "name": "Return sends", "summary": "Return or keypad Enter sends the message and gives the keys back to the editor, so Space plays while the assistant works.", "page": "assistant/chat", "anchor": "message-field-keys", "where": "Inspector ▸ Assistant tab ▸ message field", "keys": "Return", "needs": "your Anthropic key"}
27	{"id": "assistant-new-line", "name": "New line in the message field", "summary": "Return with any modifier starts a new line.", "page": "assistant/chat", "anchor": "message-field-keys", "where": "Inspector ▸ Assistant tab ▸ message field", "keys": "⇧Return"}
28	{"id": "assistant-tab-key", "name": "Tab leaves the message field", "summary": "Tab and ⇧Tab give the keys back to the editor and never type a tab.", "page": "assistant/chat", "anchor": "message-field-keys", "where": "Inspector ▸ Assistant tab ▸ message field", "keys": "Tab"}
29	{"id": "assistant-composer-undo", "name": "Undo in the message field", "summary": "⌘Z and ⇧⌘Z in the field undo and redo your typing, which never lands on the project's undo stack.", "page": "assistant/chat", "anchor": "message-field-keys", "where": "Inspector ▸ Assistant tab ▸ message field", "keys": "⌘Z"}
30	{"id": "assistant-failed-start", "name": "A failed start keeps your text", "summary": "If the conversation cannot start, the reason appears in red in the transcript and your text stays in the field.", "page": "assistant/chat", "anchor": "if-a-message-cannot-be-sent", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
31	{"id": "assistant-send-button", "name": "Send becomes Stop", "summary": "The button reads Send, and Stop while a turn is running or waiting on you.", "page": "assistant/chat", "anchor": "send-becomes-stop", "where": "Inspector ▸ Assistant tab ▸ Send", "needs": "your Anthropic key"}
32	{"id": "assistant-window-context", "name": "What each message carries", "summary": "Each message starts with a short block describing your window at the moment you sent it, so \"this clip\" and \"the selected titles\" mean what you'd expect.", "page": "assistant/chat", "anchor": "what-each-message-carries", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
33	{"id": "assistant-one-per-window", "name": "One conversation per window, never saved", "summary": "Each window has its own conversation; closing the window ends it, and conversations are not saved with the project.", "page": "assistant/chat", "anchor": "one-conversation-per-window", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
34	{"id": "assistant-clear", "name": "Clear the conversation", "summary": "The Clear button ends the conversation, empties the transcript and resets the Spend row and the meter; your next message starts a fresh conversation.", "page": "assistant/chat", "anchor": "clear-the-conversation", "where": "Inspector ▸ Assistant tab ▸ Clear (↺, \"Clear the conversation\"), at the right end of Context"}
35	{"id": "assistant-streaming-reply", "name": "Streaming replies", "summary": "The assistant's reply streams in as it is written, in regular type, under your message in semibold, and the transcript scrolls to the newest line.", "page": "assistant/conversation", "anchor": "replies", "where": "Inspector ▸ Assistant tab ▸ transcript", "needs": "your Anthropic key"}
36	{"id": "assistant-working-notes", "name": "Working notes", "summary": "The assistant's notes between tool calls appear small and faint; they are its thinking updates.", "page": "assistant/conversation", "anchor": "working-notes", "where": "Inspector ▸ Assistant tab ▸ transcript", "needs": "your Anthropic key"}
37	{"id": "assistant-tool-lines", "name": "Tool call lines", "summary": "Each tool call shows as one small monospace line with the tool's name and its arguments.", "page": "assistant/conversation", "anchor": "tool-call-lines", "where": "Inspector ▸ Assistant tab ▸ transcript", "needs": "your Anthropic key"}
38	{"id": "assistant-failed-lines", "name": "failed: lines", "summary": "A tool call that was refused shows as a failed: line with the reason.", "page": "assistant/conversation", "anchor": "failed-lines", "where": "Inspector ▸ Assistant tab ▸ transcript", "needs": "your Anthropic key"}
39	{"id": "assistant-permission-lines", "name": "Permission lines", "summary": "Each ask-first question records its outcome in the transcript as Allowed: or Declined:, with the question's sentence.", "page": "assistant/conversation", "anchor": "permission-lines", "where": "Inspector ▸ Assistant tab ▸ transcript", "needs": "your Anthropic key"}
40	{"id": "assistant-notes", "name": "Notes in the transcript", "summary": "Compaction and clearing notes, and notes about key, model or spend-ledger problems, appear in small monospace, as does the Cost line at the end of each turn.", "page": "assistant/conversation", "anchor": "notes", "where": "Inspector ▸ Assistant tab ▸ transcript", "needs": "your Anthropic key"}
41	{"id": "assistant-errors", "name": "Errors", "summary": "Errors appear in red with a specific reason.", "page": "assistant/conversation", "anchor": "errors", "where": "Inspector ▸ Assistant tab ▸ transcript", "needs": "your Anthropic key"}
42	{"id": "assistant-retries", "name": "Automatic retries", "summary": "Rate limits, outages and connection failures are retried up to three times before an error appears.", "page": "assistant/conversation", "anchor": "automatic-retries", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
43	{"id": "assistant-select-copy", "name": "Select and copy", "summary": "The transcript is one block of text, so a selection can cross entries and copies as plain text.", "page": "assistant/conversation", "anchor": "select-and-copy", "where": "Inspector ▸ Assistant tab ▸ transcript"}
44	{"id": "assistant-helper-stopped", "name": "If the helper stops", "summary": "If the assistant's helper process stops, the transcript says so, a waiting question is declined, and your next message starts a new conversation under the old transcript.", "page": "assistant/conversation", "anchor": "if-the-helper-stops", "where": "Inspector ▸ Assistant tab ▸ transcript", "needs": "your Anthropic key"}
45	{"id": "assistant-same-tools", "name": "The same tools as MCP", "summary": "The assistant works through the same tool catalog an agent uses over MCP, with a few listed exceptions, and finds tools by search rather than loading them all.", "page": "assistant/what-it-can-do", "anchor": "the-same-tools-as-mcp", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
46	{"id": "assistant-can-projects", "name": "Projects and navigation", "summary": "It can open, create and save projects, move the playhead, set the in and out range, change the selection, and enter or leave a nest.", "page": "assistant/what-it-can-do", "anchor": "projects-and-navigation", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
47	{"id": "assistant-can-tracks", "name": "Tracks, markers and the canvas", "summary": "It can add, remove, reorder and set tracks, add and edit markers, and change the canvas.", "page": "assistant/what-it-can-do", "anchor": "tracks-markers-and-the-canvas", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
48	{"id": "assistant-can-media", "name": "Media", "summary": "It can import, relink and remove media, copy it into the project (it asks first), and set a media's camera log.", "page": "assistant/what-it-can-do", "anchor": "media", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
49	{"id": "assistant-can-place", "name": "Placing clips", "summary": "It can place media, text, shapes, backgrounds, adjustment clips and graphics, and insert, overwrite, paste and duplicate.", "page": "assistant/what-it-can-do", "anchor": "placing-clips", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
50	{"id": "assistant-can-edit", "name": "Editing clips", "summary": "It can move, trim, split, slip, roll, rate-stretch, ripple-delete, lift, insert time and close gaps, detach audio and attach it again, and make J- and L-cuts.", "page": "assistant/what-it-can-do", "anchor": "editing-clips", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
51	{"id": "assistant-can-nest", "name": "Nests", "summary": "It can nest clips or take a nest apart.", "page": "assistant/what-it-can-do", "anchor": "nests", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
52	{"id": "assistant-can-speed", "name": "Speed", "summary": "It can set speed, reverse, freeze frames and add speed ramps.", "page": "assistant/what-it-can-do", "anchor": "speed", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
53	{"id": "assistant-can-look-and-sound", "name": "Look and sound", "summary": "It can change how a clip looks and sounds, including transitions, actions and zooms, rename a clip, hide or mute it, and paste attributes.", "page": "assistant/what-it-can-do", "anchor": "look-and-sound", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
54	{"id": "assistant-can-captions", "name": "Captions and words", "summary": "It can import captions, transcribe on this Mac, read a clip's timed words, and export captions.", "page": "assistant/what-it-can-do", "anchor": "captions-and-words", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
55	{"id": "assistant-can-audio", "name": "Audio clean-up", "summary": "It can find silences and filler words, normalize loudness and synchronize audio.", "page": "assistant/what-it-can-do", "anchor": "audio-clean-up", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
56	{"id": "assistant-can-export", "name": "Export", "summary": "It can export, check an export's progress, or cancel it.", "page": "assistant/what-it-can-do", "anchor": "export", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
57	{"id": "assistant-looks-at-frames", "name": "It looks at rendered frames", "summary": "The assistant renders a frame of the finished timeline through the compositor an export uses, to look before and after a visual edit.", "page": "assistant/what-it-can-do", "anchor": "it-looks-at-rendered-frames", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
58	{"id": "assistant-undo-steps", "name": "Each edit is an undo step", "summary": "Every assistant edit is its own undo step on the project, named after the edit in Edit ▸ Undo, the same as your own.", "page": "assistant/what-it-can-do", "anchor": "each-edit-is-an-undo-step", "where": "Edit ▸ Undo (⌘Z), outside the message field", "keys": "⌘Z", "needs": "your Anthropic key"}
59	{"id": "assistant-short-replies", "name": "Short replies", "summary": "Its replies are a sentence or two and don't repeat what the tool lines already show.", "page": "assistant/what-it-can-do", "anchor": "how-it-behaves", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
60	{"id": "assistant-captions-on-request", "name": "Captions only on request", "summary": "The assistant writes or restyles a caption only when you ask.", "page": "assistant/what-it-can-do", "anchor": "how-it-behaves", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
61	{"id": "assistant-effort", "name": "Medium effort, thinking on", "summary": "The model runs at medium effort with thinking on, and the faint working notes are its thinking updates.", "page": "assistant/what-it-can-do", "anchor": "how-it-behaves", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
62	{"id": "assistant-own-window", "name": "Only its own window's project", "summary": "The assistant acts only on the project in its own window, and a tool call that names another project is refused.", "page": "assistant/what-it-can-do", "anchor": "only-its-own-windows-project", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
63	{"id": "assistant-limits", "name": "The Assistant's limits", "summary": "The limits in one list.", "page": "assistant/what-it-can-do", "anchor": "limits", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
64	{"id": "assistant-withheld-tools", "name": "Tools it will not call", "summary": "Recording, closing the project and anything that uploads audio to AssemblyAI are for you to do yourself.", "page": "assistant/what-it-will-not-do", "anchor": "tools-it-will-not-call", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
65	{"id": "assistant-no-recording", "name": "It can't record", "summary": "record_screen is withheld because recording needs a person at the Record button.", "page": "assistant/what-it-will-not-do", "anchor": "tools-it-will-not-call", "where": "File ▸ New Recording… (⌥⌘N)", "keys": "⌥⌘N", "needs": "your Anthropic key"}
66	{"id": "assistant-no-close", "name": "It can't close the project", "summary": "close_project is withheld because closing the project would close the window the conversation lives in.", "page": "assistant/what-it-will-not-do", "anchor": "tools-it-will-not-call", "where": "File ▸ Close (⌘W)", "keys": "⌘W", "needs": "your Anthropic key"}
67	{"id": "assistant-no-cloud-transcribe", "name": "It can't use cloud transcription", "summary": "transcribe with the AssemblyAI engine is refused, because audio leaves the machine only when you choose it, with the price in front of you.", "page": "assistant/what-it-will-not-do", "anchor": "tools-it-will-not-call", "where": "File ▸ Generate Captions…", "needs": "your Anthropic key"}
68	{"id": "assistant-no-filler-upload", "name": "It can't transcribe for fillers", "summary": "transcribe_for_fillers is withheld because it uploads audio to the cloud.", "page": "assistant/what-it-will-not-do", "anchor": "tools-it-will-not-call", "where": "Clip ▸ Remove Filler Words…", "needs": "your Anthropic key"}
69	{"id": "assistant-ask-first", "name": "Tools it asks about first", "summary": "A tool that writes a file stops and asks, with a sentence saying what will happen and Allow and Deny buttons.", "page": "assistant/what-it-will-not-do", "anchor": "tools-it-asks-about-first", "where": "Inspector ▸ Assistant tab ▸ ask-first row (\"The assistant asks first:\") ▸ Allow, Deny", "needs": "your Anthropic key"}
70	{"id": "assistant-question-wording", "name": "What each question reads", "summary": "The question names the tool and the file it would write, and says when it would replace one.", "page": "assistant/what-it-will-not-do", "anchor": "what-each-question-reads", "where": "Inspector ▸ Assistant tab ▸ ask-first row", "needs": "your Anthropic key"}
71	{"id": "assistant-writes-without-asking", "name": "File writes that do not ask", "summary": "Some tools write files without asking: rendered frames, and graphics content inside the project's package.", "page": "assistant/what-it-will-not-do", "anchor": "file-writes-that-do-not-ask", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
72	{"id": "assistant-question-dot", "name": "The dot on the tab", "summary": "While a question waits, a small accent dot shows on the Assistant tab title, whichever inspector tab you are on.", "page": "assistant/what-it-will-not-do", "anchor": "the-dot-on-the-tab", "where": "Inspector tab strip, beside Assistant"}
73	{"id": "assistant-deny", "name": "Declining", "summary": "Deny tells the assistant you declined, and it won't retry that call in the same turn unless you ask.", "page": "assistant/what-it-will-not-do", "anchor": "declining", "where": "Inspector ▸ Assistant tab ▸ ask-first row ▸ Deny", "needs": "your Anthropic key"}
74	{"id": "assistant-question-holds-one-window", "name": "A waiting question holds only its window", "summary": "Other windows' assistants and agents over MCP keep working while one window waits for an answer.", "page": "assistant/what-it-will-not-do", "anchor": "a-waiting-question-holds-only-its-window", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
75	{"id": "assistant-rules-not-for-mcp", "name": "These rules are the Assistant's alone", "summary": "The withheld and ask-first rules belong to the Assistant: an agent over MCP drives the same tools directly and is never asked first or refused by them.", "page": "assistant/what-it-will-not-do", "anchor": "mcp-agents-are-not-bound", "where": "MCP"}
76	{"id": "assistant-stop", "name": "Stop a turn", "summary": "Click Stop, the Send button while a turn runs or a question waits, to end the request to Anthropic and halt what has not started.", "page": "assistant/stop-a-turn", "anchor": "stop-a-turn", "where": "Inspector ▸ Assistant tab ▸ Stop (the Send button while a turn runs)", "needs": "your Anthropic key"}
77	{"id": "assistant-what-stop-leaves", "name": "What stopping leaves in place", "summary": "Stop undoes nothing and ends only the turn: edits that landed stay, and your next message carries on the same conversation.", "page": "assistant/stop-a-turn", "anchor": "what-stopping-leaves-in-place", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
78	{"id": "assistant-stop-exports", "name": "Stop leaves queued exports alone", "summary": "An export is handed to the Export Queue as soon as it starts, so Stop doesn't reach it.", "page": "assistant/stop-a-turn", "anchor": "stop-and-exports", "where": "Export Queue", "needs": "your Anthropic key"}
79	{"id": "assistant-round-limit", "name": "The 30-round limit", "summary": "One turn stops after 30 rounds with the API.", "page": "assistant/stop-a-turn", "anchor": "the-30-round-limit", "where": "Inspector ▸ Assistant tab", "needs": "your Anthropic key"}
80	{"id": "assistant-wait-for-drag", "name": "Tool calls wait for your drag", "summary": "A tool call that arrives during a drag waits until you release the mouse, then runs as its own undo step after yours.", "page": "assistant/stop-a-turn", "anchor": "while-you-are-dragging", "where": "Timeline, canvas or inspector slider drags"}
81	{"id": "assistant-calls-take-turns", "name": "Tool calls take turns", "summary": "The assistant's tool calls and MCP agents' calls take turns, one at a time, and each window's calls run in order.", "page": "assistant/stop-a-turn", "anchor": "tool-calls-take-turns", "where": "Inspector ▸ Assistant tab"}
